{
  "case_id": "xsu_sg_009_medical_documentation_content",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret stemmer med afsnit 4.2 og ekspertrubrikken. Det angiver varig funktionsnedsættelse og beskrivelse, udrednings- og behandlingsforløb, diagnose hvis stillet, sygdoms- og behandlingsforløb, daglig funktion, igangværende og planlagt behandling samt erhvervsevne hvis muligt. Det gør ikke diagnosen til et ubetinget krav og fremstiller ikke behandling som valgfri. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler kravet om, at dokumentationen skal være relevant og aktuel. Det er et kritisk element i rubrikken, og aktualitet må ikke gøres irrelevant. Svaret nævner heller ikke funktionsnedsættelsens 'art og grad'. Det siger kun 'hvad funktionsnedsættelsen består i'. Øvrige elementer er dækket, herunder forbeholdet om tilgængelighed i journalen."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvad den lægelige dokumentation skal beskrive, og indeholder ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som afsnit, bestemmelse eller vejledning. Det henviser ikke til SU-bekendtgørelsen § 37 eller vejledningens afsnit 4.2."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alt væsentligt indhold kan genfindes i vejledningens afsnit 4.2 og SU-bekendtgørelsen § 37. Svaret tilføjer ingen ny regel, betingelse, myndighed eller retsvirkning."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdene 'hvis en er stillet', 'eventuelt planlagt', 'hvis muligt' og 'når oplysningerne findes i journalen' er bevaret. Aktualitetskravet i § 37, stk. 4 og vejledningen er derimod udeladt. Svaret nævner heller ikke, at tilgængelighedsforbeholdet ikke ophæver dokumentationsminimum (journaler fra egen læge, speciallæge, hospital eller klinik)."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Først angives kernen, derefter en liste over yderligere oplysninger, og der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'bør' om de enkelte oplysninger, selvom vejledningen siger, at oplysningerne 'skal fremsendes', hvis de er tilgængelige i journalen. Det svækker en pligt til en blot anbefaling. Det kan læses som, at foreliggende dokumentation om bl.a. daglig funktion er valgfri at indsende, hvilket rubrikken udpeger som en væsentlig fejl."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "yes",
      "reason": "Svaret nævner 'diagnosen, hvis en er stillet', og forbeholdet er bevaret."
    },
    "A41": {
      "label": "yes",
      "reason": "Svaret nævner sygdoms- og behandlingsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Svaret nævner sygdoms- og behandlingsforløbet og belyser udrednings- og behandlingsforløbet."
    },
    "A45": {
      "label": "yes",
      "reason": "Svaret nævner 'igangværende og eventuelt planlagt behandling'."
    },
    "A47": {
      "label": "yes",
      "reason": "Svaret nævner påvirkningen af erhvervsevnen, 'hvis det er muligt at beskrive'."
    }
  },
  "overall_notes": "Indholdsmæssigt er svaret næsten korrekt og dækker alle fem XHAILe-punkter. Det mangler dog aktualitetskravet og 'art og grad', bruger 'bør' i stedet for 'skal fremsendes', og angiver ingen kilde. Derfor er C02, C04, C08 og C10 not_met, mens C05 og C06 er not_assessable."
}

